using Automation.Helpers;
using FluentAssertions;
using Xunit;

namespace TestAutomation.Helpers;

public class Mp3DecoderTests
{
    [Fact]
    public void Decode_DecodesARealHomeAssistantCloudTtsFile()
    {
        // A real, short "Hoi" clip generated by Home Assistant Cloud's text-to-speech (mono, 24kHz, as HA Cloud TTS produces).
        var mp3 = File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Fixtures", "tts-sample.mp3"));

        var (pcm, sampleRate) = Mp3Decoder.Decode(mp3);

        sampleRate.Should().Be(24000);
        pcm.Should().NotBeEmpty();

        var samples = new short[pcm.Length / 2];
        Buffer.BlockCopy(pcm, 0, samples, 0, pcm.Length);
        samples.Max(s => Math.Abs((int)s)).Should().BeGreaterThan(1000); // actual speech, not silence
    }
}
